import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from './peopleQuery';
import { PersonForm } from './PersonForm';
import { useEditingPerson } from './useEditingPerson';
import { useShowRetired } from './useShowRetired';

function People({ sheetId }: { sheetId: string }) {
  const people = useQuery(peopleQuery(sheetId));
  const [, setEditingId] = useEditingPerson();
  const [showRetired, setShowRetired] = useShowRetired();
  // Retired people have no row at all unless "show retired" is on; their claims still count in every total.
  const listed = (people.data ?? []).filter((p) => showRetired || !p.retiredFrom);

  return (
    <section data-testid="people">
      <h3>People</h3>
      <PersonForm sheetId={sheetId} />
      <label>
        <input
          type="checkbox"
          data-testid="show-retired"
          checked={showRetired}
          onChange={(e) => setShowRetired(e.target.checked || undefined)}
        />{' '}
        Show retired
      </label>
      {people.isError && <p data-testid="people-load-error">Could not load the people.</p>}
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <th>Terms</th>
            <th>Contact</th>
            <PersonHeaders.Slot sheetId={sheetId} />
            <th />
          </tr>
        </thead>
        <tbody>
          {listed.map((p) => (
            <tr key={p.id} data-testid={`person-row-${p.id}`}>
              <td data-testid="person-name">{p.name}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <td data-testid="person-terms">{p.terms ?? ''}</td>
              <td data-testid="person-contact">{p.contact ?? ''}</td>
              <PersonCells.Slot sheetId={sheetId} personId={p.id} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => setEditingId(p.id)}>
                  Edit
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

// Keyed by sheet, so a typed name or an error never carries over to another sheet.
export const contribution = SheetPanel.fill({
  order: 10,
  Component: ({ sheetId }) => <People key={sheetId} sheetId={sheetId} />,
});
import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { usePersonError } from './usePersonError';
import { useUser } from '../session/useUser';
import { peopleKey, peopleQuery } from './peopleQuery';
import type { Person } from './peopleQuery';

/**
 * The person's aliases, sorted as names are compared, and the control that adds one. An alias shares the names'
 * uniqueness on the sheet: one equal (ignoring case) to any name or alias there is refused, as is a blank one.
 */
function PersonAliases({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [user] = useUser();
  const [alias, setAlias] = useState('');
  const [, setError] = usePersonError(personId);
  const once = useSubmitOnce();
  const person = (useQuery(peopleQuery(sheetId)).data ?? []).find((p) => p.id === personId);
  const add = useMutation({
    mutationFn: (body: { alias: string }) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/aliases`, body, user),
    onSuccess: async () => {
      setAlias('');
      await queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) });
    },
    onError: () => setError('The alias could not be added: it is blank or already in use.'),
  });

  return (
    <td>
      <span data-testid="person-aliases">{(person?.aliases ?? []).join(', ')}</span>{' '}
      <input
        data-testid="person-alias-input"
        placeholder="alias"
        value={alias}
        onChange={(e) => {
          setAlias(e.target.value);
          setError('');
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-alias-add"
        disabled={add.isPending}
        onClick={() => {
          setError('');
          const a = alias.trim();
          if (a === '') {
            setError('Type an alias.');
            return;
          }
          once(() => add.mutateAsync({ alias: a }));
        }}
      >
        Add alias
      </button>
    </td>
  );
}

// The row's `person-error` is shown by the hold cell, shared by every cell acting on the person.
export const contributions = [
  PersonHeaders.fill({ order: 9, Component: () => <th>Aliases</th> }),
  PersonCells.fill({ order: 9, Component: PersonAliases }),
];
import { getJson } from '../../api/http';
import { sheetKey } from '../sheet/sheetQuery';

export type Grade = 'A' | 'B' | 'C';
export const GRADES: Grade[] = ['A', 'B', 'C'];

/**
 * `version` is raised on every edit; an edit names the version it loaded. `retiredFrom` (yyyy-mm-dd) is
 * set once the person is retired, which they are at once, whatever the date; null otherwise. `held` is whether
 * they have any hold; `holds` are their holds by from-date: their OPEN claims dated within one, unless bound by a
 * statement, count in no live total. `terms` are their own terms in days, which come before those of their grade
 * and of the sheet; null for none. `contact` is their contact, trimmed and lower-cased, unique on the sheet; null
 * for none. `aliases` are their aliases, sorted as names are compared (ignoring case); the quick-add bar and the
 * paste box find a person by one as well as by the name.
 */
export type Person = { id: number; name: string; grade: Grade; grades: Graded[]; version: number; retiredFrom: string | null; held: boolean; holds: Held[]; terms: number | null; contact: string | null; aliases: string[] };

/** A hold from `from` to `to` inclusive (yyyy-mm-dd); `to` is null when it has no end. */
export type Held = { from: string; to: string | null };

/** Whether the date (yyyy-mm-dd) falls within any of the person's holds. */
export function heldOn(person: Person | undefined, date: string): boolean {
  return (person?.holds ?? []).some((h) => h.from <= date && (h.to === null || date <= h.to));
}

/** A grade a person was given from `from` (yyyy-mm-dd) on; null for the first, from the beginning of time. */
export type Graded = { from: string | null; grade: Grade };

/** The person's grade in force on the date (yyyy-mm-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Person | undefined, date: string): Grade | undefined {
  if (!person) return undefined;
  // No from-date sorts as '', before every date.
  const applying = person.grades.filter((g) => (g.from ?? '') <= date);
  return applying.reduce<Graded | undefined>((best, g) => (!best || (g.from ?? '') > (best.from ?? '') ? g : best), undefined)
    ?.grade ?? person.grade;
}

/** Under the sheet's key, so re-loading the sheet re-reads its people. */
export const peopleKey = (sheetId: string) => [...sheetKey(sheetId), 'people'] as const;

export const peopleQuery = (sheetId: string) => ({
  queryKey: peopleKey(sheetId),
  queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
});
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

/**
 * A person as the screen sees it. {@code grade} is the grade in force on the sheet's today; {@code grades} are
 * all the grades they were given, by from-date (yyyy-mm-dd; null for the first, from the beginning of time).
 * {@code retiredFrom} is yyyy-mm-dd, null when not retired; {@code held} is whether they have any
 * hold; {@code holds} are their holds by from-date (yyyy-mm-dd; {@code to} null when it has no end).
 * {@code terms} are their own terms in days, null for none; {@code contact} is their contact, null for none;
 * {@code aliases} are their aliases, sorted as names are compared.
 */
public record PersonResponse(long id, String name, String grade, List<Graded> grades, long version,
        String retiredFrom, boolean held, List<Held> holds, Integer terms, String contact, List<String> aliases) {

    public record Graded(String from, String grade) {
